-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'BANCO DE DADOS' and a.numero = 17
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 17 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 17', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 17 (10 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/BANCO-DE-DADOS/ATIVIDADES/ATIVIDADE-PRATICA-AULA-17.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Diga o que é um procedimento armazenado.', 0.2, 'É um conjunto de comandos SQL **guardado no banco**, com **nome e parâmetros**, que o sistema **chama** quando precisa.', 'Nota cheia (0,2): guardado no banco + chamado pelo nome. Metade (0,1): só uma parte. Zero (0): sem relação.'),
      (v_atividade, 1, 2, 'Cite duas vantagens de deixar essa regra num procedimento do banco.', 0.4, 'Duas entre: a regra fica **num lugar só** e vale para **qualquer sistema** que usa o banco; **menos idas e voltas** pela rede (uma chamada no lugar de vários comandos); **segurança** (o usuário pode ter permissão só de chamar a rotina); o banco garante a regra mesmo com **acessos simultâneos**.', 'Nota cheia (0,4): duas vantagens corretas. Metade (0,2): uma. Zero (0): nenhuma.'),
      (v_atividade, 1, 3, 'Dê um exemplo de regra que deve ficar no back-end, e não no banco, e justifique.', 0.4, 'Exemplo: **formatar os valores em reais** ou a **mensagem/cor da tela**, ou enviar e-mail de boas-vindas. Fica no back-end porque é ligada à **apresentação/tela**, não protege a integridade dos **dados**.', 'Nota cheia (0,4): exemplo adequado + justificativa. Metade (0,2): só o exemplo. Zero (0): exemplo de regra de dados (vaga, saldo).'),
      (v_atividade, 2, 1, 'Explique a diferença entre função e procedimento no PostgreSQL.', 0.2, 'A **função** devolve um valor (RETURNS) e é chamada com **SELECT**; o **procedimento** executa uma ação e é chamado com **CALL**.', 'Nota cheia (0,2): retorno + forma de chamar. Metade (0,1): só um. Zero (0): invertido.'),
      (v_atividade, 2, 2, 'Indique o tipo de cada rotina e escreva a linha de chamada de cada uma.', 0.4, 'Cálculo do valor pago = **função**: SELECT valor_pago(10); Matrícula = **procedimento**: CALL matricular(3, 2);', 'Nota cheia (0,4): tipos e chamadas corretos. Metade (0,2): tipos certos sem as chamadas, ou uma das duas. Zero (0): tipos trocados.'),
      (v_atividade, 2, 3, 'Explique o que acontece se o colega chamar o procedimento com SELECT.', 0.4, 'Dá **erro**: procedimento **não é chamado com SELECT**, e sim com **CALL** (o PostgreSQL avisa que é um procedimento).', 'Nota cheia (0,4): erro + forma correta. Metade (0,2): só "dá erro". Zero (0): diz que funciona.'),
      (v_atividade, 3, 1, 'Explique para que servem DECLARE e SELECT ... INTO.', 0.2, '**DECLARE** cria as **variáveis locais**; **SELECT ... INTO** guarda o **resultado da consulta** dentro de uma variável.', 'Nota cheia (0,2): os dois. Metade (0,1): um. Zero (0): nenhum.'),
      (v_atividade, 3, 2, 'Escreva a função valor_pago(p_matricula integer) que devolve o total pago.', 0.4, 'CREATE OR REPLACE FUNCTION valor_pago(p_matricula integer) RETURNS numeric LANGUAGE plpgsql AS $$ DECLARE v_total numeric; BEGIN SELECT coalesce(sum(valor), 0) INTO v_total FROM parcela WHERE id_matricula = p_matricula AND data_pagamento IS NOT NULL; RETURN v_total; END; $$;', 'Nota cheia (0,4): função correta (RETURNS, INTO, filtro de pagas, RETURN). Metade (0,2): falta o filtro de pagas, o INTO ou o RETURN. Zero (0): não é função ou não soma.'),
      (v_atividade, 3, 3, 'Explique por que usar coalesce na soma e escreva a chamada da função para a matrícula 10.', 0.4, 'Sem parcela paga, sum devolve **NULL**; o **coalesce** troca por **0**. Chamada: SELECT valor_pago(10);', 'Nota cheia (0,4): explicação + chamada. Metade (0,2): só um. Zero (0): nenhum.'),
      (v_atividade, 4, 1, 'Diga por que o procedimento conta só as matrículas ativas.', 0.2, 'Porque matrículas **trancadas, concluídas ou canceladas não ocupam vaga**; só as **ativas** contam para o limite.', 'Nota cheia (0,2): justificativa correta. Zero (0): sem relação.'),
      (v_atividade, 4, 2, 'Escreva o procedimento matricular(p_aluno integer, p_turma integer) com a regra de vaga.', 0.4, 'CREATE OR REPLACE PROCEDURE matricular(p_aluno integer, p_turma integer) LANGUAGE plpgsql AS $$ DECLARE v_ativos integer; BEGIN SELECT count(*) INTO v_ativos FROM matricula WHERE id_turma = p_turma AND situacao = ''ativa''; IF v_ativos >= 25 THEN RAISE EXCEPTION ''Turma % sem vaga'', p_turma; END IF; INSERT INTO matricula (id_aluno, id_turma) VALUES (p_aluno, p_turma); END; $$;', 'Nota cheia (0,4): contagem das ativas + IF >= 25 com RAISE EXCEPTION + INSERT. Metade (0,2): falta o filtro de ativas, usa > 25 ou usa NOTICE. Zero (0): não confere a vaga.'),
      (v_atividade, 4, 3, 'Explique o que acontece com o INSERT quando a turma está cheia.', 0.4, 'O **RAISE EXCEPTION** interrompe o procedimento antes do INSERT e **desfaz** tudo o que a chamada tinha feito: **nenhuma matrícula é gravada** e o erro volta para quem chamou.', 'Nota cheia (0,4): interrompe + nada gravado. Metade (0,2): só um. Zero (0): diz que a matrícula entra.'),
      (v_atividade, 5, 1, 'Explique por que duas chamadas ao mesmo tempo podem passar do limite.', 0.2, 'As duas chamadas **contam ao mesmo tempo** (cada uma vê 24 alunos), as duas acham que há vaga e as **duas inserem**.', 'Nota cheia (0,2): contagem simultânea antes do INSERT. Zero (0): sem relação.'),
      (v_atividade, 5, 2, 'Escreva o comando que trava a turma no início do procedimento e o teste de turma inexistente.', 0.4, 'PERFORM 1 FROM turma WHERE id_turma = p_turma FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION ''Turma % não existe'', p_turma; END IF;', 'Nota cheia (0,4): trava com FOR UPDATE + teste de turma inexistente. Metade (0,2): só um. Zero (0): nenhum.'),
      (v_atividade, 5, 3, 'Explique como a trava resolve o problema das duas atendentes.', 0.4, 'O **FOR UPDATE tranca a linha da turma** até o fim da transação: a **segunda chamada espera** a primeira terminar, depois conta e já encontra **25 alunos**, recebendo o erro de sem vaga.', 'Nota cheia (0,4): espera + nova contagem com o aluno novo. Metade (0,2): só "trava a turma". Zero (0): sem relação.'),
      (v_atividade, 6, 1, 'Explique a diferença entre RAISE NOTICE e RAISE EXCEPTION.', 0.2, '**NOTICE** só **mostra uma mensagem** e o procedimento **continua**; **EXCEPTION** **para** a rotina e **desfaz** a operação.', 'Nota cheia (0,2): os dois. Metade (0,1): um. Zero (0): invertidos.'),
      (v_atividade, 6, 2, 'Escreva a linha correta, com o número da turma e a quantidade de alunos na mensagem.', 0.4, 'RAISE EXCEPTION ''Turma % sem vaga (% alunos ativos)'', p_turma, v_ativos;', 'Nota cheia (0,4): EXCEPTION com os dois marcadores %. Metade (0,2): EXCEPTION sem os valores. Zero (0): mantém NOTICE.'),
      (v_atividade, 6, 3, 'Explique como o back-end fica sabendo que a turma estava cheia.', 0.4, 'A chamada CALL matricular(...) **volta com erro** e o back-end recebe a **mensagem do RAISE EXCEPTION**, que pode mostrar ao usuário.', 'Nota cheia (0,4): recebe o erro + mensagem. Metade (0,2): só "dá erro". Zero (0): sem relação.'),
      (v_atividade, 7, 1, 'Explique quando a variável FOUND fica verdadeira.', 0.2, '**FOUND** fica verdadeira quando o último comando (UPDATE, INSERT, SELECT INTO, PERFORM) **achou ou alterou pelo menos uma linha**.', 'Nota cheia (0,2): definição. Zero (0): sem relação.'),
      (v_atividade, 7, 2, 'Escreva o procedimento registrar_pagamento(p_matricula integer, p_numero smallint).', 0.4, 'CREATE OR REPLACE PROCEDURE registrar_pagamento(p_matricula integer, p_numero smallint) LANGUAGE plpgsql AS $$ BEGIN UPDATE parcela SET data_pagamento = current_date WHERE id_matricula = p_matricula AND numero = p_numero AND data_pagamento IS NULL; IF NOT FOUND THEN RAISE EXCEPTION ''Parcela %/% não encontrada ou já paga'', p_matricula, p_numero; END IF; END; $$;', 'Nota cheia (0,4): UPDATE com current_date + IF NOT FOUND com RAISE EXCEPTION. Metade (0,2): falta o teste do FOUND. Zero (0): não atualiza a parcela.'),
      (v_atividade, 7, 3, 'Explique por que o UPDATE filtra data_pagamento IS NULL e escreva a chamada para a parcela 2 da matrícula 10.', 0.4, 'Para **não registrar de novo** o pagamento de parcela **já paga** (ela não é alterada e o FOUND fica falso, gerando o erro). Chamada: CALL registrar_pagamento(10, 2::smallint);', 'Nota cheia (0,4): justificativa + chamada. Metade (0,2): só um. Zero (0): nenhum.'),
      (v_atividade, 8, 1, 'Diga qual comando do psql lista as funções e procedimentos do banco.', 0.2, '**\df**', 'Nota cheia (0,2): \df. Zero (0): outro comando.'),
      (v_atividade, 8, 2, 'Explique como trocar o corpo do procedimento sem apagá-lo antes.', 0.4, 'Usar **CREATE OR REPLACE PROCEDURE matricular(...)** com o **mesmo nome e os mesmos parâmetros**, trocando 25 por **30** no IF; o corpo é substituído sem precisar de DROP.', 'Nota cheia (0,4): CREATE OR REPLACE + mesmo nome/parâmetros. Metade (0,2): só "CREATE OR REPLACE". Zero (0): apaga e recria sem explicar, ou altera a tabela.'),
      (v_atividade, 8, 3, 'Escreva o comando que remove total_alunos e explique por que ele informa o tipo do parâmetro.', 0.4, 'DROP FUNCTION total_alunos(integer); O tipo é informado porque **pode haver rotinas com o mesmo nome** e **parâmetros diferentes**; o tipo identifica qual remover.', 'Nota cheia (0,4): comando + justificativa. Metade (0,2): só um. Zero (0): DROP TABLE ou DELETE.'),
      (v_atividade, 9, 1, 'Diga o tipo de retorno adequado para a função.', 0.2, 'Um **inteiro** (RETURNS integer ou bigint), porque a função devolve uma **quantidade**.', 'Nota cheia (0,2): tipo inteiro. Zero (0): texto ou sem retorno.'),
      (v_atividade, 9, 2, 'Escreva a função alunos_ativos(p_turma integer).', 0.4, 'CREATE OR REPLACE FUNCTION alunos_ativos(p_turma integer) RETURNS integer LANGUAGE plpgsql AS $$ DECLARE v_total integer; BEGIN SELECT count(*) INTO v_total FROM matricula WHERE id_turma = p_turma AND situacao = ''ativa''; RETURN v_total; END; $$;', 'Nota cheia (0,4): função correta com filtro de ativas e RETURN. Metade (0,2): falta o filtro de ativas ou o RETURN. Zero (0): não é função.'),
      (v_atividade, 9, 3, 'Liste as chamadas de teste que o script deve ter para o procedimento matricular e justifique.', 0.4, 'Chamadas: **caso certo** (turma com vaga, CALL matricular(3, 2)), **turma cheia** (deve dar erro de sem vaga), **turma inexistente** (deve dar erro) e **matrícula repetida** (erro do UNIQUE). Justificativa: mostrar que a rotina **funciona no caso certo e barra cada caso inválido**.', 'Nota cheia (0,4): caso certo + pelo menos dois casos de erro + justificativa. Metade (0,2): só o caso certo ou sem justificativa. Zero (0): nenhum teste.'),
      (v_atividade, 10, 1, 'Explique o erro do trecho 1 e corrija.', 0.2, 'Falta o **INTO**: o resultado não tem para onde ir e dá erro. Correção: SELECT count(*) INTO v_total FROM matricula WHERE id_turma = p_turma;', 'Nota cheia (0,2): erro + correção. Metade (0,1): só um. Zero (0): nenhum.'),
      (v_atividade, 10, 2, 'Explique o problema do trecho 2 e corrija.', 0.4, 'O parâmetro tem o **mesmo nome da coluna**: o nome fica **ambíguo** (erro) ou a condição compara a coluna com ela mesma. Correção: renomear o parâmetro para **p_turma** e usar WHERE id_turma = p_turma.', 'Nota cheia (0,4): ambiguidade + correção com prefixo. Metade (0,2): só um. Zero (0): nenhum.'),
      (v_atividade, 10, 3, 'Explique o erro do trecho 3 e escreva a chamada correta.', 0.4, 'valor_pago é uma **função**: não se chama com **CALL**, e sim dentro de um **SELECT**. Correção: SELECT valor_pago(10);', 'Nota cheia (0,4): erro + chamada correta. Metade (0,2): só um. Zero (0): nenhum.');
end $$;
